'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const n = input[idx++];
const graph = Array.from({ length: n }, () => []);

for (let i = 0; i < n - 1; i++) {
  const x = input[idx++] - 1;
  const y = input[idx++] - 1;
  graph[x].push(y);
  graph[y].push(x);
}

function bfs(start, withParent) {
  const dist = new Int32Array(n);
  dist.fill(-1);
  const parent = withParent ? new Int32Array(n) : null;
  const queue = new Int32Array(n);
  let head = 0;
  let tail = 0;
  queue[tail++] = start;
  dist[start] = 0;
  let farthest = start;

  while (head < tail) {
    const u = queue[head++];
    if (dist[u] > dist[farthest]) farthest = u;

    for (const v of graph[u]) {
      if (dist[v] !== -1) continue;
      dist[v] = dist[u] + 1;
      if (withParent) parent[v] = u;
      queue[tail++] = v;
    }
  }

  return { farthest, dist, parent };
}

const endpointA = bfs(0, false).farthest;
const result = bfs(endpointA, true);
const endpointB = result.farthest;
const diameter = result.dist[endpointB];

const path = [];
for (let v = endpointB; ; v = result.parent[v]) {
  path.push(v);
  if (v === endpointA) break;
}
path.reverse();

let ways = 0;

if (diameter % 2 === 0) {
  const center = path[diameter / 2];
  const targetDepth = diameter / 2;
  let nodesSeen = 0;

  for (const first of graph[center]) {
    const stackNode = [first];
    const stackParent = [center];
    const stackDepth = [1];
    let count = 0;

    while (stackNode.length) {
      const u = stackNode.pop();
      const p = stackParent.pop();
      const depth = stackDepth.pop();

      if (depth === targetDepth) {
        count++;
        continue;
      }

      for (const v of graph[u]) {
        if (v === p) continue;
        stackNode.push(v);
        stackParent.push(u);
        stackDepth.push(depth + 1);
      }
    }

    ways += nodesSeen * count;
    nodesSeen += count;
  }
} else {
  const middle = diameter >> 1;
  const leftCenter = path[middle];
  const rightCenter = path[middle + 1];
  const targetDepth = middle;

  function countSide(start, blocked) {
    const stackNode = [start];
    const stackParent = [blocked];
    const stackDepth = [0];
    let count = 0;

    while (stackNode.length) {
      const u = stackNode.pop();
      const p = stackParent.pop();
      const depth = stackDepth.pop();

      if (depth === targetDepth) {
        count++;
        continue;
      }

      for (const v of graph[u]) {
        if (v === p) continue;
        stackNode.push(v);
        stackParent.push(u);
        stackDepth.push(depth + 1);
      }
    }

    return count;
  }

  ways = countSide(leftCenter, rightCenter) * countSide(rightCenter, leftCenter);
}

console.log(`${diameter + 1}\n${ways}`);
